import numpy as np

emb = {
    'king': np.array([5., 1.]), 'man': np.array([1., 1.]),
    'woman': np.array([1., 4.]), 'queen': np.array([5., 4.]),
    'apple': np.array([0.2, 0.1]),
}

def cos(u, v):
    return u @ v / (np.linalg.norm(u) * np.linalg.norm(v))

def analogy(a, b, c):
    q = emb[a] - emb[b] + emb[c]
    cands = [w for w in emb if w not in (a, b, c)]  # 질문 단어는 뺀다
    return max(cands, key=lambda w: cos(q, emb[w]))

print(analogy('king', 'man', 'woman'))  # queen

# RNN 한 걸음씩: 순서대로만 계산할 수 있다
rng = np.random.default_rng(0)
Wh, Wx = rng.normal(size=(3, 3)) * 0.5, rng.normal(size=(3, 2)) * 0.5
h = np.zeros(3)
for w in ['king', 'man', 'woman']:
    h = np.tanh(Wh @ h + Wx @ emb[w])
print(h)  # 문장 전체가 3차원 벡터 하나로 눌린다

import numpy as np

# 아주 작은 밀집 검색기: 문서 벡터와 질문 벡터의 코사인으로 상위 k 개
docs = {
    'd1': '사전학습은 무작위 가중치에서 시작한다',
    'd2': 'RAG 는 검색한 문서를 문맥에 넣는다',
    'd3': '고양이는 상자를 좋아한다',
}
vocab = sorted({w for t in docs.values() for w in t.split()} | {'검색', '문서'})

def embed(text):
    v = np.array([text.split().count(w) for w in vocab], float)
    return v / (np.linalg.norm(v) + 1e-9)

D = {k: embed(t) for k, t in docs.items()}

def retrieve(q, k=1):
    qv = embed(q)
    return sorted(D, key=lambda d: -qv @ D[d])[:k]

q = 'RAG 는 무엇을 문맥에 넣나'
ctx = [docs[d] for d in retrieve(q)]
prompt = '참고: ' + ' / '.join(ctx) + '\n질문: ' + q
print(prompt)  # 이 prompt 를 LLM 에 넣는 것이 RAG

import torch.nn as nn

class TinyLM(nn.Module):
    def __init__(self, vocab=1000, d=64, n_layers=8):
        super().__init__()
        self.embed = nn.Embedding(vocab, d)
        self.layers = nn.ModuleList(
            nn.TransformerEncoderLayer(d, 4, 4 * d, batch_first=True)
            for _ in range(n_layers))
        self.norm, self.lm = nn.LayerNorm(d), nn.Linear(d, vocab)

    def grow(self, n_new):
        """기존 층·임베딩·norm·lm 은 그대로, 위에 무작위 층만 더한다"""
        d = self.embed.embedding_dim
        for _ in range(n_new):
            self.layers.append(nn.TransformerEncoderLayer(d, 4, 4 * d, batch_first=True))

schedule = [(8, 'easy', .2), (10, 'mid', .2), (12, 'hard', .2), (16, 'hardest', .4)]
model, budget = TinyLM(n_layers=8), 20_000_000_000
for n_layers, level, frac in schedule:
    model.grow(n_layers - len(model.layers))
    print(n_layers, level, int(budget * frac))  # 여기서 해당 난이도 데이터로 학습

def run_agent(goal, llm, tools, max_steps=5):
    memory = []                                   # Reflexion 식 반성 기록
    for step in range(max_steps):
        context = {'goal': goal, 'memory': memory}            # 1 인식
        plan = llm(f'계획을 세워라: {context}')                # 2 추론
        tool, arg = plan['tool'], plan['arg']
        result = tools[tool](arg)                              # 3 행동
        ok, feedback = result['ok'], result['msg']            # 4 관찰
        if ok:
            return result
        memory.append(llm(f'왜 실패했나: {feedback}'))          # 5 반성
    return {'ok': False, 'memory': memory}

# 흉내 낸 LLM 과 도구: 첫 시도는 문법 오류, 반성 후 고친다
def fake_llm(prompt):
    if prompt.startswith('계획'):
        fixed = '괄호' in prompt
        return {'tool': 'run', 'arg': 'print(1)' if fixed else 'print(1'}
    return '괄호를 닫지 않았다'

def run(code):
    try:
        exec(code); return {'ok': True, 'msg': 'done'}
    except SyntaxError as e:
        return {'ok': False, 'msg': str(e)}

print(run_agent('1을 출력', fake_llm, {'run': run}))

import numpy as np

def ssm_scan(x, A, B, C, D=0.0):
    """1차원 상태 공간 모델: 상태 하나로 수열 전체를 처리, O(n)"""
    h, ys = 0.0, []
    for xt in x:
        h = A * h + B * xt
        ys.append(C * h + D * xt)
    return np.array(ys)

print(ssm_scan([4, 0, 0, 2], A=0.5, B=1, C=2))   # [8. 4. 2. 5.]

def selective_scan(x, gate):
    """Mamba 의 '선택성' 흉내: 입력마다 유지율·쓰기 강도가 달라진다"""
    h, ys = 0.0, []
    for xt in x:
        g = gate(xt)                 # 중요하면 g≈1 (강하게 쓰고 덮어씀)
        h = (1 - g) * h + g * xt
        ys.append(h)
    return np.array(ys)

important = lambda v: 1.0 if abs(v) > 5 else 0.05
print(selective_scan([9, 1, 1, 1, 1], important))  # 9 를 오래 기억한다
